theme_eeg <- function(base_size = 13) {
  theme_minimal(base_size = base_size) +
    theme(panel.grid.minor = element_blank(),
          panel.grid.major.x = element_blank(),
          panel.grid.major.y = element_line(color = "#E3E3E3", linewidth = 0.4),
          axis.line.x = element_line(color = "#B0B0B0", linewidth = 0.4),
          plot.title = element_text(face = "bold", size = base_size + 2),
          plot.subtitle = element_text(color = "#555555"),
          plot.caption = element_text(color = "#777777", size = base_size - 3, hjust = 0),
          strip.text = element_text(face = "bold", size = base_size - 1),
          legend.position = "top",
          legend.title = element_blank(),
          plot.background = element_rect(fill = "white", color = NA))
}
save_fig <- function(plot, name, height_px = 900) {
  # 1400 px wide at 150 dpi = 9.33 in wide; the text stays readable when shown 1000 px wide
  ggsave(file.path(fig_dir, name), plot, width = 1400 / 150, height = height_px / 150,
         dpi = 150, bg = "white")
  cat("saved figure:", file.path("figures", name), "\n")
}
wrap_txt <- function(x, w) paste(strwrap(x, width = w), collapse = "\n")
# p value in APA style for figure labels
fp <- function(p) ifelse(p < .001, "p < .001", paste0("p = ", sub("^0", "", sprintf("%.3f", p))))
# p value for the output file: five decimals, scientific notation below 0.0001
pf <- function(p) ifelse(p < 0.0001, sprintf("%.2e", p), sprintf("%.5f", p))
# Wilcoxon and Mann Whitney statistics: whole number, or one decimal when ties give a half rank
fv <- function(v) ifelse(abs(v - round(v)) < 1e-9, sprintf("%.0f", v), sprintf("%.1f", v))
ci95 <- function(x) { x <- x[!is.na(x)]; qt(0.975, length(x) - 1) * sd(x) / sqrt(length(x)) }

# Confidence limits for a standardized effect size from the NONCENTRAL t distribution (the exact
# method; Lakens, 2013). The observed t is treated as a draw from a t distribution with an unknown
# noncentrality parameter (ncp); the 95% limits are the two ncp values for which the observed t sits
# at the 97.5th and the 2.5th percentile. Dividing the ncp limits by sqrt(n) (one sample) or
# multiplying them by sqrt(1/n1 + 1/n2) (two samples) turns them into d limits.
nct_limits <- function(t_obs, df, conf = 0.95) {
  a <- (1 - conf) / 2
  f <- function(ncp, target) suppressWarnings(pt(t_obs, df, ncp)) - target
  lo <- uniroot(f, c(t_obs - 12, t_obs + 12), target = 1 - a, tol = 1e-12)$root
  hi <- uniroot(f, c(t_obs - 12, t_obs + 12), target = a, tol = 1e-12)$root
  c(lo, hi)
}

# ---- Helper: one sample t test on change scores (the same as a paired t test) ---------
# x_ref and x_cmp are the two measurements of the same respondents; change = x_cmp - x_ref.
# Cohen's d_z = mean change / SD of the changes, the effect size of a paired design
# (t = d_z * sqrt(n)). Two 95% intervals are printed: the exact one from the noncentral t
# distribution and the large sample approximation SE(d_z) = sqrt(1 / n + d_z^2 / (2 n)) that the
# Excel workbook uses.
report_change <- function(x_ref, x_cmp, label, nm_ref, nm_cmp, id, unit = "FA units") {
  ok <- !is.na(x_ref) & !is.na(x_cmp)
  a <- x_ref[ok]; b <- x_cmp[ok]; chg <- b - a; n <- length(chg)
  tt <- t.test(chg, mu = 0)
  dz <- mean(chg) / sd(chg)
  lim <- nct_limits(unname(tt$statistic), n - 1) / sqrt(n)
  se_d <- sqrt(1 / n + dz^2 / (2 * n))
  wx <- suppressWarnings(wilcox.test(b, a, paired = TRUE, exact = FALSE))
  sw <- shapiro.test(chg)
  p_one <- pt(unname(tt$statistic), n - 1, lower.tail = FALSE)
  cat(sprintf("%s\n", label))
  cat(sprintf("  %s: M = %.3f, SD = %.3f, n = %d\n", nm_ref, mean(a), sd(a), n))
  cat(sprintf("  %s: M = %.3f, SD = %.3f, n = %d\n", nm_cmp, mean(b), sd(b), n))
  cat(sprintf("  Change (%s minus %s): M = %.3f %s, SD = %.3f, 95%% CI [%.3f, %.3f]\n",
              nm_cmp, nm_ref, mean(chg), unit, sd(chg), tt$conf.int[1], tt$conf.int[2]))
  cat(sprintf("  One sample t on the change (= paired t): t(%d) = %.2f, p = %s (two tailed); one tailed p = %s (teaching only)\n",
              n - 1, tt$statistic, pf(tt$p.value), pf(p_one)))
  cat(sprintf("  Cohen's d_z = %.2f, 95%% CI [%.2f, %.2f] (noncentral t); approximation [%.2f, %.2f]\n",
              dz, lim[1], lim[2], dz - 1.96 * se_d, dz + 1.96 * se_d))
  cat(sprintf("  Wilcoxon signed rank V = %s, p = %s\n", fv(wx$statistic), pf(wx$p.value)))
  cat(sprintf("  Shapiro Wilk on the changes: W = %.3f, p = %.3f\n", sw$statistic, sw$p.value))
  cat(sprintf("  Respondents with a positive change: %d of %d\n\n", sum(chg > 0), n))
  invisible(list(id = id, test = "one sample t on the change (paired)", label = label, n = n, n1 = NA_integer_, n2 = NA_integer_,
                 m1 = mean(a), m2 = mean(b), sd1 = sd(a), sd2 = sd(b), diff = mean(chg), sd_diff = sd(chg),
                 sd_pooled = NA_real_, ci_lo = tt$conf.int[1], ci_hi = tt$conf.int[2],
                 t = unname(tt$statistic), df = n - 1, p = tt$p.value, p_one = p_one,
                 es_type = "d_z", es = dz, es_lo = lim[1], es_hi = lim[2],
                 es_lo_approx = dz - 1.96 * se_d, es_hi_approx = dz + 1.96 * se_d,
                 g = NA_real_, g_lo = NA_real_, g_hi = NA_real_, g_lo_approx = NA_real_, g_hi_approx = NA_real_,
                 np_stat = unname(wx$statistic), np_p = wx$p.value, shapiro_p = sw$p.value, chg = chg))
}

# ---- Helper: one sample t test of raw scores against zero (sensitivity only) ------------
report_vs_zero <- function(x, label, id) {
  x <- x[!is.na(x)]; n <- length(x)
  tt <- t.test(x, mu = 0)
  d <- mean(x) / sd(x)
  lim <- nct_limits(unname(tt$statistic), n - 1) / sqrt(n)
  se_d <- sqrt(1 / n + d^2 / (2 * n))
  wx <- suppressWarnings(wilcox.test(x, mu = 0, exact = FALSE))
  sw <- shapiro.test(x)
  p_one <- pt(unname(tt$statistic), n - 1, lower.tail = FALSE)
  cat(sprintf("%s\n", label))
  cat(sprintf("  M = %.3f, SD = %.3f, n = %d, 95%% CI [%.3f, %.3f]\n", mean(x), sd(x), n, tt$conf.int[1], tt$conf.int[2]))
  cat(sprintf("  One sample t against 0: t(%d) = %.2f, p = %s (two tailed); one tailed p = %s\n", n - 1, tt$statistic, pf(tt$p.value), pf(p_one)))
  cat(sprintf("  Cohen's d = %.2f, 95%% CI [%.2f, %.2f] (noncentral t)\n", d, lim[1], lim[2]))
  cat(sprintf("  Wilcoxon signed rank V = %s, p = %s\n", fv(wx$statistic), pf(wx$p.value)))
  cat(sprintf("  Respondents with a positive score: %d of %d\n\n", sum(x > 0), n))
  invisible(list(id = id, test = "one sample t against zero", label = label, n = n, n1 = NA_integer_, n2 = NA_integer_,
                 m1 = NA_real_, m2 = mean(x), sd1 = NA_real_, sd2 = sd(x), diff = mean(x), sd_diff = sd(x),
                 sd_pooled = NA_real_, ci_lo = tt$conf.int[1], ci_hi = tt$conf.int[2],
                 t = unname(tt$statistic), df = n - 1, p = tt$p.value, p_one = p_one,
                 es_type = "d (one sample)", es = d, es_lo = lim[1], es_hi = lim[2],
                 es_lo_approx = d - 1.96 * se_d, es_hi_approx = d + 1.96 * se_d,
                 g = NA_real_, g_lo = NA_real_, g_hi = NA_real_, g_lo_approx = NA_real_, g_hi_approx = NA_real_,
                 np_stat = unname(wx$statistic), np_p = wx$p.value, shapiro_p = sw$p.value, chg = x))
}

# ---- Helper: Welch t test between two groups ------------------------------------------
# Welch's t does not assume equal variances (Delacre, Lakens, & Leys, 2017). Cohen's d uses the
# pooled SD; Hedges' g = J x d with the small sample correction J = 1 - 3 / (4 (n1 + n2) - 9).
# Their exact 95% limits come from the noncentral t distribution of the pooled (Student) t; the
# approximation SE(d) = sqrt((n1 + n2) / (n1 n2) + d^2 / (2 (n1 + n2))) is what Excel uses.
report_welch <- function(xa, xb, label, nm_a, nm_b, id) {
  xa <- xa[!is.na(xa)]; xb <- xb[!is.na(xb)]
  n1 <- length(xa); n2 <- length(xb)
  wt <- t.test(xa, xb, var.equal = FALSE)
  st <- t.test(xa, xb, var.equal = TRUE)
  sp <- sqrt(((n1 - 1) * var(xa) + (n2 - 1) * var(xb)) / (n1 + n2 - 2))
  d <- (mean(xa) - mean(xb)) / sp
  J <- 1 - 3 / (4 * (n1 + n2) - 9)
  g <- J * d
  lim <- nct_limits(unname(st$statistic), n1 + n2 - 2) * sqrt(1 / n1 + 1 / n2)
  se_d <- sqrt((n1 + n2) / (n1 * n2) + d^2 / (2 * (n1 + n2)))
  se_g <- sqrt((n1 + n2) / (n1 * n2) + g^2 / (2 * (n1 + n2)))
  mw <- suppressWarnings(wilcox.test(xa, xb, exact = FALSE))
  sw_a <- shapiro.test(xa); sw_b <- shapiro.test(xb)
  p_one <- pt(unname(wt$statistic), unname(wt$parameter), lower.tail = FALSE)
  cat(sprintf("%s\n", label))
  cat(sprintf("  %s: M = %.3f, SD = %.3f, n = %d\n", nm_a, mean(xa), sd(xa), n1))
  cat(sprintf("  %s: M = %.3f, SD = %.3f, n = %d\n", nm_b, mean(xb), sd(xb), n2))
  cat(sprintf("  Difference (%s minus %s) = %.3f, 95%% CI [%.3f, %.3f] (Welch)\n", nm_a, nm_b, mean(xa) - mean(xb),
              wt$conf.int[1], wt$conf.int[2]))
  cat(sprintf("  Welch t(%.2f) = %.2f, p = %s (two tailed); one tailed p = %s (teaching only)\n",
              wt$parameter, wt$statistic, pf(wt$p.value), pf(p_one)))
  cat(sprintf("  Student t(%d) = %.2f, p = %s (equal variances assumed; used only for the d interval)\n",
              n1 + n2 - 2, st$statistic, pf(st$p.value)))
  cat(sprintf("  Pooled SD = %.3f; Cohen's d = %.2f, 95%% CI [%.2f, %.2f]; Hedges' g = %.2f, 95%% CI [%.2f, %.2f] (noncentral t)\n",
              sp, d, lim[1], lim[2], g, J * lim[1], J * lim[2]))
  cat(sprintf("  Approximate intervals: d [%.2f, %.2f], g [%.2f, %.2f]\n", d - 1.96 * se_d, d + 1.96 * se_d, g - 1.96 * se_g, g + 1.96 * se_g))
  cat(sprintf("  Mann Whitney W = %s, p = %s\n", fv(mw$statistic), pf(mw$p.value)))
  cat(sprintf("  Shapiro Wilk: %s p = %.3f, %s p = %.3f; variance ratio (larger / smaller) = %.2f\n\n",
              nm_a, sw_a$p.value, nm_b, sw_b$p.value, max(var(xa), var(xb)) / min(var(xa), var(xb))))
  invisible(list(id = id, test = "Welch t (two groups)", label = label, n = n1 + n2, n1 = n1, n2 = n2,
                 m1 = mean(xa), m2 = mean(xb), sd1 = sd(xa), sd2 = sd(xb), diff = mean(xa) - mean(xb), sd_diff = NA_real_,
                 sd_pooled = sp, ci_lo = wt$conf.int[1], ci_hi = wt$conf.int[2],
                 t = unname(wt$statistic), df = unname(wt$parameter), p = wt$p.value, p_one = p_one,
                 es_type = "d (pooled SD)", es = d, es_lo = lim[1], es_hi = lim[2],
                 es_lo_approx = d - 1.96 * se_d, es_hi_approx = d + 1.96 * se_d,
                 g = g, g_lo = J * lim[1], g_hi = J * lim[2], g_lo_approx = g - 1.96 * se_g, g_hi_approx = g + 1.96 * se_g,
                 np_stat = unname(mw$statistic), np_p = mw$p.value, shapiro_p = min(sw_a$p.value, sw_b$p.value),
                 shapiro_a = sw_a$p.value, shapiro_b = sw_b$p.value, xa = xa, xb = xb))
}

# ---- STEP 1. Read the files -----------------------------------------------------------
# The first line of every file is a "# SIMULATED" comment (the two FA files have a second comment
# line, the METADATA block), so comment = "#" skips them. A real iMotions export has no such lines.
# NA is how a metric that could not be calculated is written (for example a segment in which every
# 1 s window was removed by the artifact threshold).
fa_raw  <- read_csv("SIMULATED_eeg_fa_metrics.csv", comment = "#", na = c("NA", ""), show_col_types = FALSE)
dfa_raw <- read_csv("SIMULATED_eeg_fa_metrics_default_channels.csv", comment = "#", na = c("NA", ""), show_col_types = FALSE)
psd_raw <- read_csv("SIMULATED_eeg_psd_metrics.csv", comment = "#", na = c("NA", ""), show_col_types = FALSE)
art_raw <- read_csv("SIMULATED_eeg_artifact_report.csv", comment = "#", na = c("NA", ""), show_col_types = FALSE)
session <- read_csv("SIMULATED_eeg_session_log.csv", comment = "#", na = c("NA", ""), show_col_types = FALSE)
survey  <- read_csv("SIMULATED_eeg_survey.csv", comment = "#", na = c("NA", ""), show_col_types = FALSE)

cat("---- STEP 1. Files read ----\n")
cat("FA export rows:", nrow(fa_raw), " respondents:", n_distinct(fa_raw$`Respondent Name`), "\n")
cat("FA export columns:", paste(names(fa_raw), collapse = " | "), "\n")
cat("Type values:", paste(sort(unique(fa_raw$Type)), collapse = ", "), "\n")
cat("Labels:", paste(unique(fa_raw$Label), collapse = ", "), "\n")
cat("FA export with default channels rows:", nrow(dfa_raw), "  PSD export rows:", nrow(psd_raw),
    " (", ncol(psd_raw), " columns)\n", sep = "")
cat("Artifact report rows:", nrow(art_raw), "  Session log rows:", nrow(session), "  Survey rows:", nrow(survey), "\n")
fa_cols <- c("Study Name", "Respondent Name", "Gender", "Age", "Group", "Type", "Label", "Start (ms)",
             "Duration (ms)", "Parent Stimulus", "Mean Frontal Asymmetry Alpha", "Algorithm Device Name")
stopifnot(identical(names(fa_raw), fa_cols), identical(names(dfa_raw), fa_cols))
psd_metric_cols <- grep("^Mean PSD ", names(psd_raw), value = TRUE)
cat("PSD metric columns (", length(psd_metric_cols), "): ", paste(head(psd_metric_cols, 4), collapse = " | "),
    " | ... | ", paste(tail(psd_metric_cols, 2), collapse = " | "), "\n\n", sep = "")

# A segment is identified by Label AND Parent Stimulus: "EndScene" appears on all three commercials.
# role names the part of the design a row belongs to:
#   Baseline_1, Baseline_2, C1 (Commercial_1A or Commercial_1B), C2, KeyScene, EndScene_C1, EndScene_C2
add_role <- function(d) {
  d %>% mutate(
    respondent = `Respondent Name`,
    version = substr(Group, 1, 1),
    order = sub("^[AB]_", "", Group),
    role = case_when(
      Type == "Stimulus" & startsWith(Label, "Baseline") ~ Label,
      Type == "Stimulus" & startsWith(Label, "Commercial_1") ~ "C1",
      Type == "Stimulus" & Label == "Commercial_2" ~ "C2",
      Label == "KeyScene" ~ "KeyScene",
      Label == "EndScene" & startsWith(`Parent Stimulus`, "Commercial_1") ~ "EndScene_C1",
      Label == "EndScene" & `Parent Stimulus` == "Commercial_2" ~ "EndScene_C2",
      TRUE ~ NA_character_))
}
fa  <- add_role(fa_raw)  %>% rename(fa = `Mean Frontal Asymmetry Alpha`)
dfa <- add_role(dfa_raw) %>% rename(fa = `Mean Frontal Asymmetry Alpha`)
psd <- add_role(psd_raw)
stopifnot(!anyNA(fa$role))
role_levels <- c("Baseline_1", "Baseline_2", "C1", "C2", "KeyScene", "EndScene_C1", "EndScene_C2")

# ---- STEP 2. Channel map and notebook settings ---------------------------------------
# The Enobio reports its channels as Ch1, Ch2, ... and the scalp site of each channel is set by the
# protocol in NIC2. The FA notebook asks for a left and a right frontal electrode; its Enobio
# defaults are Ch1 (left) and Ch7 (right). Under the lab manual montage those are Fz and P3.
cat("---- STEP 2. Channel map and notebook settings ----\n")
meta <- grep("^# METADATA", readLines("SIMULATED_eeg_fa_metrics.csv", n = 3), value = TRUE)
cat("FA export settings:", sub("^# ", "", meta), "\n")
montage <- tibble(channel = paste0("Ch", 1:8), site_assumed = c("Fz", "Cz", "Pz", "Oz", "F3", "F4", "P3", "P4"),
                  used_for = c("FA default LEFT (wrong)", "", "", "", "FA LEFT (used)", "FA RIGHT (used)", "FA default RIGHT (wrong)", ""))
print(as.data.frame(montage), row.names = FALSE)
# A plausibility check of the montage from the PSD export: alpha is normally strongest over the
# back of the head (parietal and occipital sites), so the channels assumed to be Pz, Oz, P3, and P4
# should show the highest alpha power during the baselines. This supports the map; it does not
# prove it (only the NIC2 protocol does).
alpha_topo <- psd %>% filter(role %in% c("Baseline_1", "Baseline_2")) %>%
  summarize(across(all_of(paste0("Mean PSD Ch", 1:8, " Alpha (dB)")), ~ mean(.x, na.rm = TRUE))) %>%
  pivot_longer(everything(), names_to = "column", values_to = "alpha_db") %>%
  mutate(channel = sub("Mean PSD (Ch[0-9]) Alpha \\(dB\\)", "\\1", column)) %>%
  left_join(montage %>% select(channel, site_assumed), by = "channel") %>%
  transmute(channel, site_assumed, mean_alpha_db_baselines = round(alpha_db, 2))
cat("\nMean alpha power (dB) in the baselines, all 48 respondents:\n"); print(as.data.frame(alpha_topo), row.names = FALSE)
cat(sprintf("Mean baseline FA: %.3f with Ch5/Ch6 (F3/F4) versus %.3f with the default Ch1/Ch7 (Fz/P3).\n",
