                                                      `NIC2 quality F4 before recording` == "Red" ~ "F4", TRUE ~ ""))
screen <- art_worst %>% left_join(log_red, by = "respondent") %>%
  left_join(fa %>% distinct(respondent, version, order), by = "respondent")
apply_rule <- function(limit) {
  screen %>% mutate(over = max_pct > limit,
                    why = case_when(over & red ~ sprintf("Red at %s before recording; %.2f percent removed (%s)", red_site, max_pct, worst),
                                    red ~ sprintf("Red at %s before recording", red_site),
                                    over ~ sprintf("%.2f percent removed (%s)", max_pct, worst),
                                    TRUE ~ NA_character_))
}
scr25 <- apply_rule(25)
excluded <- scr25 %>% filter(!is.na(why))
