            sum(is.na(fa$fa)), sum(is.na(dfa$fa)), sum(is.na(as.matrix(psd[, psd_metric_cols])))))
if (any(is.na(fa$fa))) print(as.data.frame(fa %>% filter(is.na(fa)) %>% select(respondent, Label, `Parent Stimulus`)), row.names = FALSE)
# FA and PSD come from the same alpha power. In dB, Ch6 alpha minus Ch5 alpha equals
# 10 log10(right / left) = (10 / ln 10) x ln(right / left), so dividing that dB difference by 4.343
# gives an FA like score. It is not identical to the exported FA (the PSD export averages power over
# time BEFORE the log, the FA notebook averages the 1 s FA values, and the two notebooks drop
# windows per channel versus per electrode pair), but the two must agree closely.
psd_fa <- psd %>% transmute(respondent, Label, `Parent Stimulus`, Type,
                            fa_psd = (`Mean PSD Ch6 Alpha (dB)` - `Mean PSD Ch5 Alpha (dB)`) / (10 / log(10))) %>%
  left_join(fa %>% select(respondent, Label, `Parent Stimulus`, fa), by = c("respondent", "Label", "Parent Stimulus")) %>%
  filter(respondent %in% kept_ids)
cat(sprintf("  FA from the PSD export, (Ch6 alpha dB - Ch5 alpha dB) / 4.343, against the exported FA (kept respondents, %d rows): r = %.3f, mean difference = %.4f\n\n",
            sum(!is.na(psd_fa$fa)), cor(psd_fa$fa, psd_fa$fa_psd, use = "complete.obs"), mean(psd_fa$fa_psd - psd_fa$fa, na.rm = TRUE)))

# ---- STEP 5. One row per kept respondent; baseline corrected scores ------------------------
# The baseline that PRECEDES a commercial depends on the order: for C1first respondents
# Commercial_1 follows Baseline_1 and Commercial_2 follows Baseline_2; for C2first respondents it is
# the other way round. A change score is the segment minus its preceding baseline.
cat("---- STEP 5. Analysis table: one row per kept respondent ----\n")
make_wide <- function(d, ids) {
  d %>% filter(respondent %in% ids) %>% select(respondent, version, order, role, fa) %>%
    pivot_wider(names_from = role, values_from = fa) %>%
    mutate(bl_c1 = if_else(order == "C1first", Baseline_1, Baseline_2),
           bl_c2 = if_else(order == "C1first", Baseline_2, Baseline_1),
           chg_ks  = KeyScene - bl_c1,
           chg_es1 = EndScene_C1 - bl_c1,
           chg_es2 = EndScene_C2 - bl_c2,
           chg_c1  = C1 - bl_c1,
           chg_c2  = C2 - bl_c2,
           chg_diff = chg_c2 - chg_c1) %>%
    arrange(respondent)
}
w <- make_wide(fa, kept_ids)
stopifnot(nrow(w) == n_kept, !anyNA(w$chg_c1), !anyNA(w$chg_c2), !anyNA(w$chg_es1), !anyNA(w$chg_ks[w$version == "A"]))
cat("First six rows (FA units):\n")
print(as.data.frame(w %>% select(respondent, version, order, bl_c1, KeyScene, EndScene_C1, C1, bl_c2, C2, chg_ks, chg_es1, chg_c1, chg_c2) %>%
                      mutate(across(where(is.numeric), ~ round(.x, 3))) %>% head(6)), row.names = FALSE)
cat("\n")

# ---- STEP 6. Descriptive statistics ---------------------------------------------------
cat("---- STEP 6. Descriptive statistics (kept respondents) ----\n")
desc_row <- function(x, measure, segment, version) {
  x <- x[!is.na(x)]
  tibble(measure = measure, segment = segment, version = version, n = length(x), mean = mean(x), sd = sd(x),
         median = median(x), min = min(x), max = max(x), ci_low = mean(x) - ci95(x), ci_high = mean(x) + ci95(x))
}
seg_names <- c(Baseline_1 = "Baseline_1", Baseline_2 = "Baseline_2", C1 = "Commercial_1 (1A or 1B)", C2 = "Commercial_2",
               KeyScene = "KeyScene (Commercial_1A)", EndScene_C1 = "EndScene of Commercial_1", EndScene_C2 = "EndScene of Commercial_2")
chg_names <- c(chg_ks = "KeyScene minus its baseline", chg_es1 = "EndScene_C1 minus its baseline", chg_es2 = "EndScene_C2 minus its baseline",
               chg_c1 = "Commercial_1 minus its baseline", chg_c2 = "Commercial_2 minus its baseline",
               chg_diff = "Change Commercial_2 minus change Commercial_1")
desc <- bind_rows(
  lapply(names(seg_names), function(s) bind_rows(
    lapply(c("A", "B"), function(v) if (s == "KeyScene" && v == "B") NULL else desc_row(w[[s]][w$version == v], "FA (raw)", seg_names[[s]], v)),
    if (s != "KeyScene") desc_row(w[[s]], "FA (raw)", seg_names[[s]], "All") else NULL)),
  lapply(names(chg_names), function(s) bind_rows(
    lapply(c("A", "B"), function(v) if (s == "chg_ks" && v == "B") NULL else desc_row(w[[s]][w$version == v], "FA change from baseline", chg_names[[s]], v)),
    if (s != "chg_ks") desc_row(w[[s]], "FA change from baseline", chg_names[[s]], "All") else NULL)))
print(as.data.frame(desc %>% select(measure, segment, version, n, mean, sd, min, max) %>% mutate(across(where(is.double), ~ round(.x, 3)))), row.names = FALSE)
cat(sprintf("\nMost FA scores are negative: %d of %d baseline rows (%.1f percent) are below zero, as in the demo study chart.\n",
            sum(c(w$Baseline_1, w$Baseline_2) < 0), 2 * n_kept, 100 * mean(c(w$Baseline_1, w$Baseline_2) < 0)))
bl_t <- t.test(w$Baseline_2, w$Baseline_1, paired = TRUE)
cat(sprintf("Baselines: Baseline_1 M = %.3f (SD = %.3f), Baseline_2 M = %.3f (SD = %.3f); paired t(%d) = %.2f, p = %s; r = %.2f\n",
            mean(w$Baseline_1), sd(w$Baseline_1), mean(w$Baseline_2), sd(w$Baseline_2), n_kept - 1, bl_t$statistic, pf(bl_t$p.value),
            cor(w$Baseline_1, w$Baseline_2)))
cat("The two baselines are comparable, and a respondent's FA is stable across them (a trait like level); this stable part\n")
cat("is what the baseline correction removes.\n")
wA <- w %>% filter(version == "A")
cat(sprintf("Why the key scene is noisier (Version A, n = %d): the 6 s KeyScene holds 11 one second Welch windows, Commercial_1A 119.\n", nrow(wA)))
cat(sprintf("  SD of the change from baseline: KeyScene %.3f versus whole Commercial_1A %.3f (ratio %.2f)\n",
            sd(wA$chg_ks), sd(wA$chg_c1), sd(wA$chg_ks) / sd(wA$chg_c1)))
cat(sprintf("  Correlation with the preceding baseline: KeyScene r = %.2f versus whole Commercial_1A r = %.2f\n\n",
            cor(wA$KeyScene, wA$bl_c1), cor(wA$C1, wA$bl_c1)))
write_csv(desc, "SIMULATED_descriptives.csv")
cat("written: SIMULATED_descriptives.csv\n\n")

# ---- STEP 7. H1: key scene versus its baseline (Version A) -----------------------------------
cat("---- STEP 7. H1: KeyScene minus the baseline before Commercial_1A (Version A) ----\n")
res_h1 <- report_change(wA$bl_c1, wA$KeyScene, sprintf("H1: FA change during the key scene (Version A, kept, n = %d)", nrow(wA)),
                        "Baseline before Commercial_1A", "KeyScene", "H1")
if (has_effectsize) {
  es_chk <- effectsize::cohens_d(res_h1$chg, ci = 0.95, verbose = FALSE)
  cat(sprintf("Cross-check with the effectsize package: d_z = %.4f, 95%% CI [%.4f, %.4f] (hand computed: %.4f [%.4f, %.4f])\n\n",
              es_chk$Cohens_d, es_chk$CI_low, es_chk$CI_high, res_h1$es, res_h1$es_lo, res_h1$es_hi))
}

# ---- STEP 8. H2: end scene of Commercial 1, Version A versus Version B -------------------------
cat("---- STEP 8. H2: baseline corrected EndScene of Commercial 1, Version A versus Version B ----\n")
res_h2 <- report_welch(w$chg_es1[w$version == "A"], w$chg_es1[w$version == "B"],
                       sprintf("H2: EndScene_C1 change, Version A (with key scene) versus Version B (without), n = %d and %d", nA, nB),
                       "Version A", "Version B", "H2")
# Power note. power.t.test assumes two equal groups and equal variances; it answers "how many
# respondents per version would a new study need to detect an effect of this size 80 percent of the
# time at alpha = .05 (two tailed)?"
pw_n <- power.t.test(delta = res_h2$es, sd = 1, sig.level = 0.05, power = 0.80)$n
n_h <- 2 / (1 / nA + 1 / nB)
pw_now <- power.t.test(n = n_h, delta = res_h2$es, sd = 1, sig.level = 0.05)$power
cat(sprintf("Power note: at the observed d = %.2f, a new study needs n = %d respondents PER VERSION (%d in total) for 80%% power\n",
            res_h2$es, ceiling(pw_n), 2 * ceiling(pw_n)))
cat(sprintf("(two tailed, alpha = .05). With %d and %d respondents (harmonic mean %.1f) the power at this d was %.2f.\n",
            nA, nB, n_h, pw_now))
pw_n_h1 <- power.t.test(delta = res_h1$es, sd = 1, sig.level = 0.05, power = 0.80, type = "one.sample")$n
cat(sprintf("For comparison, a within subjects test like H1 at d_z = %.2f needs n = %d for 80%% power.\n", res_h1$es, ceiling(pw_n_h1)))
cat(sprintf("EndScene_C1 change above zero: Version A %d of %d, Version B %d of %d\n\n",
            sum(res_h2$xa > 0), nA, sum(res_h2$xb > 0), nB))

# ---- STEP 9. H3: Commercial_2 versus Commercial_1 -------------------------------------------
cat("---- STEP 9. H3: baseline corrected whole commercial FA, Commercial_2 versus Commercial_1 (paired) ----\n")
res_h3 <- report_change(w$chg_c1, w$chg_c2, sprintf("H3: change Commercial_2 minus change Commercial_1 (all kept, n = %d)", n_kept),
                        "Commercial_1 change", "Commercial_2 change", "H3")
cat(sprintf("Correlation of a respondent's two commercial changes: r = %.2f\n\n", cor(w$chg_c1, w$chg_c2)))

# Mixed model. Each respondent contributes two change scores (one per commercial), so the rows are
# not independent; a random intercept per respondent absorbs that. Codes (-0.5 / +0.5), so each
# coefficient is a full difference between two levels averaged over the other factors:
#   commercial1          = Commercial_2 minus Commercial_1
#   version1             = Version A minus Version B
#   position1            = second minus first viewing (fatigue or carryover)
#   commercial1:version1 = the difference (Commercial_2 minus Commercial_1) in Version A minus the
#                          same difference in Version B, a between subjects contrast
cat("---- STEP 9b. Mixed model: FA_change ~ commercial * version + position + (1 | respondent) ----\n")
mm_data <- bind_rows(
  w %>% transmute(respondent, version, order, commercial = "C1", fa_change = chg_c1, position = if_else(order == "C1first", "first", "second")),
  w %>% transmute(respondent, version, order, commercial = "C2", fa_change = chg_c2, position = if_else(order == "C1first", "second", "first"))) %>%
  mutate(commercial = factor(commercial, levels = c("C1", "C2")), version = factor(version, levels = c("B", "A")),
         position = factor(position, levels = c("first", "second"))) %>%
  as.data.frame()
contrasts(mm_data$commercial) <- c(-0.5, 0.5)
contrasts(mm_data$version)    <- c(-0.5, 0.5)
contrasts(mm_data$position)   <- c(-0.5, 0.5)
mm <- lmerTest::lmer(fa_change ~ commercial * version + position + (1 | respondent), data = mm_data, REML = TRUE)
print(summary(mm, correlation = FALSE))
cat("\nType III tests (Satterthwaite degrees of freedom):\n")
print(anova(mm, type = 3))
cf <- as.data.frame(coef(summary(mm)))
names(cf) <- c("est", "se", "df", "t", "p")
cf$ci_lo <- cf$est - qt(0.975, cf$df) * cf$se
cf$ci_hi <- cf$est + qt(0.975, cf$df) * cf$se
term_labels <- c("(Intercept)" = "Intercept (grand mean change)",
                 "commercial1" = "Commercial (Commercial_2 minus Commercial_1)",
                 "version1" = "Version (A minus B)",
                 "position1" = "Position (second minus first)",
                 "commercial1:version1" = "Commercial x version")
cat("\nFixed effects with 95% CI (estimate +/- t(Satterthwaite df) x SE):\n")
for (nm in rownames(cf)) {
  cat(sprintf("  %-46s b = %7.4f, SE = %.4f, df = %5.1f, t = %6.2f, p = %s, 95%% CI [%.4f, %.4f]\n",
              term_labels[[nm]], cf[nm, "est"], cf[nm, "se"], cf[nm, "df"], cf[nm, "t"], pf(cf[nm, "p"]), cf[nm, "ci_lo"], cf[nm, "ci_hi"]))
}
vc <- as.data.frame(VarCorr(mm))
var_resp <- vc$vcov[vc$grp == "respondent"]; var_res <- vc$vcov[vc$grp == "Residual"]
icc_adj <- var_resp / (var_resp + var_res)
mm0 <- lme4::lmer(fa_change ~ 1 + (1 | respondent), data = mm_data, REML = TRUE)
vc0 <- as.data.frame(VarCorr(mm0))
icc_null <- vc0$vcov[vc0$grp == "respondent"] / sum(vc0$vcov)
cat(sprintf("\nICC (adjusted, from the fitted model) = %.3f  (respondent variance %.5f, residual variance %.5f)\n", icc_adj, var_resp, var_res))
cat(sprintf("ICC (unconditional, intercept only model) = %.3f\n", icc_null))
cat(sprintf("Singular fit: %s\n", isSingular(mm)))
cat("A low ICC is expected here: the baseline correction already removed the stable person level (the trait),\n")
cat("so little of what remains is shared by a respondent's two change scores.\n")
# Simple estimates that Excel can reproduce. For C1first respondents Commercial_2 was seen second, so
# their difference (C2 change minus C1 change) = commercial effect + position effect; for C2first
# respondents it is commercial effect - position effect.
dif_by <- w %>% group_by(order) %>% summarize(m = mean(chg_diff), n = n(), .groups = "drop")
m1f <- dif_by$m[dif_by$order == "C1first"]; m2f <- dif_by$m[dif_by$order == "C2first"]
pos_simple <- (m1f - m2f) / 2
comm_simple <- (m1f + m2f) / 2
int_simple <- mean(w$chg_diff[w$version == "A"]) - mean(w$chg_diff[w$version == "B"])
