            mean(link$like_c1[link$version == "A"]), sd(link$like_c1[link$version == "A"]), nA,
            mean(link$like_c1[link$version == "B"]), sd(link$like_c1[link$version == "B"]), nB,
            mean(link$like_c2), sd(link$like_c2), n_kept))
