            sum(link$recall == "Yes", na.rm = TRUE), nA, 100 * mean(link$recall[link$version == "A"] == "Yes"),
            sum(link$brand == "Yes"), n_kept, 100 * mean(link$brand == "Yes")))
cor_report <- function(x, y, label, id) {
  ct <- cor.test(x, y)
  sp <- suppressWarnings(cor.test(x, y, method = "spearman", exact = FALSE))
  cat(sprintf("%s: r(%d) = %.2f, 95%% CI [%.2f, %.2f], p = %s; Spearman rho = %.2f, p = %s\n",
              label, as.integer(ct$parameter), ct$estimate, ct$conf.int[1], ct$conf.int[2], pf(ct$p.value),
              sp$estimate, pf(sp$p.value)))
  invisible(list(id = id, label = label, r = unname(ct$estimate), df = unname(ct$parameter), t = unname(ct$statistic),
                 p = ct$p.value, lo = ct$conf.int[1], hi = ct$conf.int[2], rho = unname(sp$estimate), p_rho = sp$p.value))
}
c_1 <- cor_report(link$chg_c1, link$like_c1, "Commercial_1 FA change with Liking_Commercial_1_1to7", "cor_C1")
c_2 <- cor_report(link$chg_c2, link$like_c2, "Commercial_2 FA change with Liking_Commercial_2_1to7", "cor_C2")
cat("Approach is not the same as liking (approach can come from anger or curiosity), so a modest correlation is the expected result.\n")
