cat(sprintf("KeyScene change by recall (descriptive only): recalled M = %.3f (n = %d), not recalled M = %.3f (n = %d)\n\n",
            ks_rec$m[ks_rec$recall == "Yes"], ks_rec$n[ks_rec$recall == "Yes"], ks_rec$m[ks_rec$recall == "No"], ks_rec$n[ks_rec$recall == "No"]))

