  pivot_wider(names_from = role, values_from = c(theta_fz, alpha_cl)) %>%
  mutate(th_c1 = theta_fz_C1 - if_else(order == "C1first", theta_fz_Baseline_1, theta_fz_Baseline_2),
         th_c2 = theta_fz_C2 - if_else(order == "C1first", theta_fz_Baseline_2, theta_fz_Baseline_1),
         al_c1 = alpha_cl_C1 - if_else(order == "C1first", alpha_cl_Baseline_1, alpha_cl_Baseline_2),
         al_c2 = alpha_cl_C2 - if_else(order == "C1first", alpha_cl_Baseline_2, alpha_cl_Baseline_1))
th_desc <- function(x, nm) cat(sprintf("  %s: M = %+.2f dB, SD = %.2f, 95%% CI [%+.2f, %+.2f], higher than baseline for %d of %d respondents\n",
                                     nm, mean(x), sd(x), mean(x) - ci95(x), mean(x) + ci95(x), sum(x > 0), length(x)))
cat("Frontal midline theta (Mean PSD Ch1 Theta (dB), assumed Fz), commercial minus its preceding baseline:\n")
th_desc(pw$th_c1, "Commercial_1"); th_desc(pw$th_c2, "Commercial_2")
th_both <- (pw$th_c1 + pw$th_c2) / 2
th_desc(th_both, "Mean of the two commercials")
cat("Electrode cluster average alpha (all 8 channels), commercial minus its preceding baseline:\n")
