# ---- STEP 11. Sensitivity analyses ------------------------------------------------------------
cat("---- STEP 11. Sensitivity analyses ----\n")
# (a) Stricter exclusion threshold: 15 percent instead of 25 percent (the Red rule is unchanged).
scr15 <- apply_rule(15)
ex15 <- scr15 %>% filter(!is.na(why))
extra15 <- setdiff(ex15$respondent, ex_ids)
cat(sprintf("(a) Threshold 15 percent: %d respondents excluded (%d more than the main rule): %s\n", nrow(ex15), length(extra15),
            paste(sprintf("%s (Version %s, %.2f percent, %s)", extra15, scr15$version[match(extra15, scr15$respondent)],
                          scr15$max_pct[match(extra15, scr15$respondent)], scr15$worst[match(extra15, scr15$respondent)]), collapse = "; ")))
w15 <- w %>% filter(!respondent %in% extra15)
nA15 <- sum(w15$version == "A"); nB15 <- sum(w15$version == "B")
cat(sprintf("    Kept: %d (Version A %d, Version B %d)\n\n", nrow(w15), nA15, nB15))
res_s1 <- report_change(w15$bl_c1[w15$version == "A"], w15$KeyScene[w15$version == "A"],
                        sprintf("Sensitivity H1, 15 percent threshold (n = %d)", nA15), "Baseline before Commercial_1A", "KeyScene", "S15_H1")
res_s2 <- report_welch(w15$chg_es1[w15$version == "A"], w15$chg_es1[w15$version == "B"],
                       sprintf("Sensitivity H2, 15 percent threshold (n = %d and %d)", nA15, nB15), "Version A", "Version B", "S15_H2")
# (b) Without baseline correction. H1 then asks whether the raw KeyScene FA is above zero, and H2
# compares the raw EndScene FA of the two versions. FA has no meaningful zero point (it carries each
# respondent's stable asymmetry), which is why the planned tests use change scores.
cat("(b) Without baseline correction\n")
res_u1 <- report_vs_zero(wA$KeyScene, sprintf("Sensitivity H1 without baseline correction: raw KeyScene FA against 0 (n = %d)", nrow(wA)), "RAW_H1")
res_u2 <- report_welch(w$EndScene_C1[w$version == "A"], w$EndScene_C1[w$version == "B"],
                       sprintf("Sensitivity H2 without baseline correction: raw EndScene_C1 FA (n = %d and %d)", nA, nB), "Version A", "Version B", "RAW_H2")
cat(sprintf("The SD of the raw EndScene_C1 FA (pooled %.3f) is larger than the SD of its change score (pooled %.3f): the baseline\n",
            res_u2$sd_pooled, res_h2$sd_pooled))
cat(sprintf("correction removes the stable between person differences. The baselines of the two versions differed by %.3f by chance\n",
            mean(w$bl_c1[w$version == "A"]) - mean(w$bl_c1[w$version == "B"])))
cat("(Version A minus Version B), and the raw comparison carries that difference along with the effect.\n\n")

