cat("---- STEP 13. Assumption checks ----\n")
swt <- tibble(test = c("H1 KeyScene change (Version A)", "H2 EndScene_C1 change, Version A", "H2 EndScene_C1 change, Version B",
                       "H3 difference of the commercial changes"),
              n = c(res_h1$n, res_h2$n1, res_h2$n2, res_h3$n),
              shapiro_p = round(c(res_h1$shapiro_p, res_h2$shapiro_a, res_h2$shapiro_b, res_h3$shapiro_p), 3))
