print(as.data.frame(swt), row.names = FALSE)
cat(sprintf("Variance ratio of the H2 groups (larger / smaller) = %.2f; Welch's t does not need equal variances.\n",
            max(var(res_h2$xa), var(res_h2$xb)) / min(var(res_h2$xa), var(res_h2$xb))))
