  scale_shape_manual(values = c(F3 = 16, F4 = 17), labels = c(F3 = "F3 (Ch5)", F4 = "F4 (Ch6)")) +
  scale_x_continuous(limits = c(0, 75), breaks = seq(0, 70, 10)) +
  labs(title = "SIMULATED: artifact screening, largest percent of samples removed per respondent",
       subtitle = "Largest value over the two baselines and two commercials, at F3 and at F4 (artifact threshold 120 microvolts).",
       x = "Percent of samples removed (largest stimulus)", y = NULL,
       caption = wrap_txt("SIMULATED teaching data (make_simulated_data.py); the artifact report layout is modeled. A respondent is excluded when any baseline or commercial loses more than 25 percent of its F3 or F4 samples, or when NIC2 showed a Red status at F3 or F4 that could not be fixed before recording.", 125)) +
  theme_eeg(12) + theme(panel.grid.major.y = element_blank(), panel.grid.major.x = element_line(color = "#E3E3E3", linewidth = 0.4),
                        axis.text.y = element_text(size = 8.5))
save_fig(fig4, "SIMULATED_fig4_artifact_screening.png", 1450)
cat("\n")

