row_of <- function(r, nm) tibble(id = r$id, test = r$test, comparison = nm, n = r$n, n1 = r$n1, n2 = r$n2,
                                 m1 = r$m1, m2 = r$m2, sd1 = r$sd1, sd2 = r$sd2, mean_diff = r$diff, sd_diff = r$sd_diff,
                                 sd_pooled = r$sd_pooled, diff_ci_low = r$ci_lo, diff_ci_high = r$ci_hi, t = r$t, df = r$df,
                                 p = r$p, p_one_tailed = r$p_one, es_type = r$es_type, es = r$es, es_ci_low = r$es_lo, es_ci_high = r$es_hi,
                                 es_ci_low_approx = r$es_lo_approx, es_ci_high_approx = r$es_hi_approx,
                                 g = r$g, g_ci_low = r$g_lo, g_ci_high = r$g_hi, g_ci_low_approx = r$g_lo_approx, g_ci_high_approx = r$g_hi_approx,
                                 nonparam_stat = r$np_stat, nonparam_p = r$np_p, shapiro_p = r$shapiro_p)
tests <- bind_rows(
  row_of(res_h1, "H1: KeyScene minus the baseline before Commercial_1A (Version A); m1 = baseline, m2 = KeyScene"),
  row_of(res_h2, "H2: EndScene_C1 change, Version A minus Version B (Welch); m1 = A, m2 = B"),
  row_of(res_h3, "H3: change Commercial_2 minus change Commercial_1 (paired); m1 = C1 change, m2 = C2 change"),
  row_of(res_s1, "Sensitivity H1, 15 percent threshold"),
  row_of(res_s2, "Sensitivity H2, 15 percent threshold"),
  row_of(res_u1, "Sensitivity H1 without baseline correction (raw KeyScene FA against 0)"),
  row_of(res_u2, "Sensitivity H2 without baseline correction (raw EndScene_C1 FA)"),
  row_of(res_d1, "Teaching contrast: H1 with the notebook default channels (Ch1 = Fz, Ch7 = P3)"))
cat("---- Summary of the tests ----\n")
print(as.data.frame(tests %>% select(id, n, n1, n2, m1, m2, mean_diff, t, df, p, es_type, es, es_ci_low, es_ci_high, nonparam_stat, nonparam_p) %>%
                      mutate(across(where(is.numeric), ~ round(.x, 4)))), row.names = FALSE)
write_csv(tests, "SIMULATED_test_results.csv")
cat("written: SIMULATED_test_results.csv\n")

